// ~~ © Zeiierman {
//@version=6
indicator('Timely Opening Range Breakout Strategy [TORB] (Zeiierman)', shorttitle = 'TORB (Zeiierman)', overlay = true)
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// ~~ Tooltips {
t1 = 'Defines the specific time range for the trading session. Adjusting this setting changes the period during which the Timely Opening Range Breakout (TORB) strategy is applied.'
t2 = 'Specifies the time zone for the trading session input. Changing this setting will shift the session window according to the selected time zone, allowing the strategy to align with the trading hours of different global markets.'
t3 = 'Enables or disables the highlighting of the high and low range during the specified session. Turning this on visualizes the session\'s price range, aiding in identifying potential breakout levels. '
t4 = 'Activates the volume analysis component of the strategy. Enabling this setting incorporates volume data into the breakout signals, aiming to add confirmation to the strength of breakouts. Increasing the sensitivity to volume can highlight significant moves, while decreasing it may result in a broader set of signals.'
t5 = 'Sets the lookback period for calculating the average volume, which influences the volume moving average (PMMV). A longer period smoothens the volume curve, potentially filtering out noise but also delaying response to volume spikes. A shorter period makes the volume indicator more responsive to recent changes.'
t6 = 'Determines the weight given to the volume in the strategy\'s calculations. Increasing this value amplifies the impact of volume on the PMMV, making the strategy more sensitive to volume changes. Decreasing it reduces the influence of volume.'
t7 = 'Adjusts the sensitivity of the volume component by setting the bounds for volume oscillation. \n\nEnable \'Stocks\' and lower the \'volume sensitivity\' if you don\'t get any signals.'
t8 = 'Enables or disables the generation of breakout signals based on the strategy\'s criteria. Activating this feature will allow the indicator to highlight potential breakout points above or below the defined session range, based on volume and price movement.'
t9 = 'The threshold level, calculated as a percentage of the session\'s high-low range, serves as a criterion for assessing market activity. If the PMMV exceeds this threshold, it suggests heightened market activity. Increasing this percentage raises the activity level required to signal potential breakouts, making the strategy more selective. Decreasing it lowers the activity threshold, potentially increasing the frequency of breakout signals but with a risk of including less significant movements.'
t10 = 'Turns on or off the visualization of the breakout threshold level on the chart. Enabling this setting helps to identify the price level at which a breakout signal would be generated, providing a clear target for observing potential breakouts'
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// ~~ Inputs {
session = input.session('0900-1000', 'Session', inline = 'sess', group = 'Session', tooltip = t1)
utc = input.string('UTC+1', '', inline = 'sess', group = 'Session', tooltip = t2)
hilo = input.bool(true, 'Session Range', inline = 'range', group = 'Session', tooltip = t3)
sessionVol = input.bool(false, 'Session Volume', inline = 'range', group = 'Session')
up = input.color(color.new(color.red, 0), '', inline = 'range', group = 'Session')
dn = input.color(color.new(color.lime, 0), '', inline = 'range', group = 'Session')
bgcol = input.color(color.new(color.blue, 0), '', inline = 'range', group = 'Session')

vol = input.bool(true, 'Volume', inline = 'volc', group = 'PMMV', tooltip = t4)
volc = input.color(color.rgb(64, 204, 209), '', inline = 'volc', group = 'PMMV')
style = input.string('Line', '', ['Line', 'Area'], inline = 'volc', group = 'PMMV')

N = input.int(20, title = 'Volume Period', minval = 1, inline = '', group = 'PMMV', tooltip = t5)
pow = input.float(5.0, title = 'Volume Significance', minval = 1, inline = '', group = 'PMMV', tooltip = t6)
sig = input.int(10, minval = 1, step = 2, maxval = 100, title = 'Volume Sensitivity', inline = 'sig', group = 'PMMV') * 100
stocks = input.bool(false, title = 'Stocks', inline = 'sig', group = 'PMMV', tooltip = t7)

br = input.bool(true, 'Breakout', inline = 'br', group = 'Breakout Signals', tooltip = t8)
percentage = input.float(30, title = 'Breakout Thresold %', minval = 0, maxval = 100, group = 'Breakout Signals', inline = 'percentage', tooltip = t9) / 100
BreakoutThresold = input.bool(false, title = '', group = 'Breakout Signals', inline = 'percentage')
bt = input.color(color.blue, '', group = 'Breakout Signals', inline = 'percentage')
bu = input.color(color.lime, '', inline = 'br', group = 'Breakout Signals')
bd = input.color(color.red, '', inline = 'br', group = 'Breakout Signals')
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// ~~ Variables {
b = bar_index
sess = not na(time(timeframe.period, session, utc))
SignalUp = false
SignalDn = false
var hi = float(na)
var lo = float(na)
var res = 1
var box openingBox = na
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// ~~ Function {
conditionloop(cond_) =>
    conditionMet = true
    for i = 1 to 20 by 1
        if cond_[i]
            conditionMet := false
            conditionMet
    conditionMet
    //~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// ~~ Session {
if sess and not sess[1]
    hi := high
    lo := low
    res := 1
    openingBox := box.new(left = bar_index, top = hi, right = bar_index + 1, bottom = lo, bgcolor = color.new(bgcol, 85), border_color = bgcol, border_width = 1)
    openingBox

if sess
    hi := math.max(hi, high)
    lo := math.min(lo, low)
    res := res + 1
    box.set_right(openingBox, bar_index + 1)
    box.set_top(openingBox, hi)
    box.set_bottom(openingBox, lo)
    //~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// ~~  Calculate PMMV as the average volume over the last N days {
nVol = math.sum(volume, N) / N
d = stocks ? math.avg(ta.lowest(nVol * nVol, sig), ta.highest(nVol * nVol, sig)) : ta.highest(nVol * nVol, sig)
PMMV = lo + nVol * nVol * (lo - (lo - (hi - lo) * .15)) * pow / d
avgMa = ta.sma(PMMV, res)
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// ~~ TORB Signal Conditions {
closehi= ta.crossover(close, hi)
closelo= ta.crossunder(close, lo)
level = lo + (hi - lo) * percentage
breakUp = PMMV > avgMa and PMMV >= level and closehi
breakDn = PMMV > avgMa and PMMV >= level and closelo

condUpOk = conditionloop(breakUp)
condDnOk = conditionloop(breakDn)

SignalUp := breakUp and condUpOk
SignalDn := breakDn and condDnOk
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// ~~ Plots {
nosess = not sess

v1 = plot(vol ? ta.wma(PMMV, 5) : na, title = 'PMMV', style = plot.style_stepline, color = sessionVol ? volc : nosess ? volc : na)
v2 = plot(BreakoutThresold ? level : na, title = 'Breakout Thresold Level', color = nosess ? bt : na)
p1 = plot(hilo ? hi : na, 'Range High', color = nosess ? up : na, offset = +1)
p2 = plot(hilo ? lo : na, 'Range Low', color = nosess ? dn : na, offset = +1)
fill(v1, p2, vol and style == 'Area' and nosess ? color.new(volc, 50) : na)

plotshape(br ? SignalUp : false, 'TORB - Break Up', shape.triangleup, location.belowbar, bu, size = size.small)
plotshape(br ? SignalDn : false, 'TORB - Break Dn', shape.triangledown, location.abovebar, bd, size = size.small)
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// ~~ Alerts {
//Session
alertcondition(sess and not sess[1], 'Session Start', 'Session has started!')
alertcondition(sess[1] and not sess, 'Session End', 'Session has ended!')

//Breakout
alertcondition(breakUp, 'TORB - Break Up', 'TORB - Break Up')
alertcondition(breakDn, 'TORB - Break Dn', 'TORB - Break Dn')
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~}

// This Pine Script™ code is subject to the terms of the Mozilla Public License 2.0 at https://mozilla.org/MPL/2.0/
// © exlux99

//@version=5
strategy("Opening Range Breakout (ORB) Heikin Ashi SPY 5min Correlation Strategy", overlay=true)


///////// relative volume
import TradingView/ta/7

anchorTimeframeInput = input.timeframe("W", "Anchor Timeframe", tooltip = "When Chart Timeframe >= `Anchor Timeframe`, the indicator will use last `Length` bars in its calculations.", group="RVOL parameters")
lengthInput          = input.int(3, "Length", minval = 1, group="RVOL parameters")

[currentVolume, pastVolume, _] = ta.relativeVolume(lengthInput, anchorTimeframeInput, true)

// Input parameters
sessionTime = input.session("0930-1000", "Session Time Opening", group="Time Session")
sessionTradingTime = input.session("1000-1200", "Session Time Trading", group="Time Session")
sessionEndTime = input.session("1550-1555", "Session Time Ending", group="Time Session")
useHeikinAshi = input(false, "Use Heikin Ashi?", group="Correlation Parameters")
asset_correlation = input.symbol("SPY", group="Correlation Parameters", title="Symbol used for Correlation")

// Session flags
inSession = not na(time(timeframe.period, sessionTime + ":1234567"))
inTradingSession = not na(time(timeframe.period, sessionTradingTime + ":1234567"))
endSession = not na(time(timeframe.period, sessionEndTime + ":1234567"))

// high/low correlation candle calculations
high_ = useHeikinAshi ?  request.security(ticker.heikinashi(asset_correlation), timeframe.period, high) : request.security(asset_correlation, timeframe.period, high)
low_ = useHeikinAshi ?  request.security(ticker.heikinashi(asset_correlation), timeframe.period, low) : request.security(asset_correlation, timeframe.period, low)


// Initialize variables to store the previous session's high and low
var float prevSessionHigh = na
var float prevSessionLow = na

// Update previous session's high and low if a new session begins
if (inSession and not inSession[1])
    prevSessionHigh := high_
    prevSessionLow := low_

// Keep track of the current session's high and low
currentSessionHigh = prevSessionHigh[1]
currentSessionLow = prevSessionLow[1]

// Update current session's high and low if necessary
if (high_ > currentSessionHigh and inSession)
    currentSessionHigh := high_

if (low_ < currentSessionLow and inSession)
    currentSessionLow := low_

// Plotting
plot( currentSessionHigh , color=color.green, title="ORB High", linewidth=2)
plot( currentSessionLow  , color=color.red, title="ORB Low", linewidth=2)

// Trading logic
longCondition = close > currentSessionHigh and inTradingSession
shortCondition = close < currentSessionLow and inTradingSession

var bool longTrade = na
var bool shortTrade = na


rvol = currentVolume / pastVolume 

if (longCondition and not shortTrade and rvol > 1 )
    longTrade := true
if (shortCondition and not longTrade and rvol > 1)
    shortTrade := true

if (endSession)
    longTrade := na
    shortTrade := na

plotshape(longTrade[1] or shortTrade[1] ? endSession : na,style=shape.labeldown, location=location.abovebar, color=color.new(color.purple, 0), size=size.tiny, title='EXIT', text='END SESSION', textcolor=color.new(color.white, 0))


strategy.entry("long", strategy.long, when=longTrade)
strategy.entry("short", strategy.short, when=shortTrade)

strategy.close_all(when=endSession)

// This Pine Script™ code is subject to the terms of the Mozilla Public License 2.0 at https://mozilla.org/MPL/2.0/
// © Shivam_Mandrai

//@version=6
strategy('IU Opening range Breakout Strategy', overlay = true)

//________________________________ User input ___________________________________________________\\
RTR = input.float(2.00, 'RTR =  ', tooltip = 'Set the Risk To Reward')
max_trades = input.int(2, 'Max trades in a day = ') * 2
days_end_time = input.session("1500-1515", "End of day Time = ", tooltip = "At this time all of the open potions will close")
//----------- setting the max trade allow ---------- \\
strategy.risk.max_intraday_filled_orders(max_trades, 'Max trade allow limit is filled')

//________________________________ Getting the Opening range ____________________________________\\
opening_range_high = ta.valuewhen(session.isfirstbar, high, 0)
opening_range_low = ta.valuewhen(session.isfirstbar, low, 0)
//-----plotting high and low ---- \\
plot(opening_range_high, 'Opening range high', color.lime, 2, style = plot.style_circles)
plot(opening_range_low, 'Opening range high', color.red, 2, style = plot.style_circles)


//_______________________________ goning long and short __________________________________________\\
//----- going long -----\\
if ta.crossover(close, opening_range_high) and strategy.position_size == 0 and barstate.isconfirmed
    strategy.entry('long', strategy.long, comment = 'Long Entry')
    //----- going short ----\\
if ta.crossunder(close, opening_range_low) and strategy.position_size == 0 and barstate.isconfirmed
    strategy.entry('short', strategy.short, comment = 'short Entry')


//______________________________ long SL and TP ___________________________________________________\\
//------ previous candle low as an SL --------\\
long_SL = ta.valuewhen(strategy.position_size > 0 and strategy.position_size[1] == 0, low[1], 0)
long_TP = strategy.position_avg_price + (strategy.position_avg_price - long_SL) * RTR
if strategy.position_size > 0
    strategy.exit('long', 'long', stop = long_SL, limit = long_TP, comment = 'long Exit')


//______________________________ short SL and TP ___________________________________________________\\
//------ previous candle high as an SL --------\\
short_SL = ta.valuewhen(strategy.position_size < 0 and strategy.position_size[1] == 0, high[1], 0)
short_TP = strategy.position_avg_price - (short_SL - strategy.position_avg_price) * RTR
if strategy.position_size < 0
    strategy.exit('short', 'short', stop = short_SL, limit = short_TP, comment = 'short Exit')


//______________________________ Plotting long and short SL , TP ___________________________________\\
// ---- for long positions ------ \\
long_SL_plot = plot(strategy.position_size[1] > 0 ? long_SL : na, 'Long SL', color.red, style = plot.style_linebr)
long_TP_plot = plot(strategy.position_size[1] > 0 ? long_TP[1] : na, 'Long TP', color.green, style = plot.style_linebr)
// ---- for short positions ----- \\
short_SL_plot = plot(strategy.position_size[1] < 0 ? short_SL : na, 'Short SL', color.red, style = plot.style_linebr)
short_TP_plot = plot(strategy.position_size[1] < 0 ? short_TP[1] : na, 'Short SL', color.green, style = plot.style_linebr)


//______________________________ Exit at the end of the day _____________________________________\\
end_of_day = time("", days_end_time)
if not na(end_of_day)
    strategy.close_all("End of the day exit")


//______________________________ Filling stop loss and take profits ______________//
entry_plot = plot(strategy.position_size[1] != 0 ? strategy.position_avg_price[1] : na, color = color.new(color.silver, 20), style = plot.style_linebr)
// ------------- for long ----------- \\
fill(entry_plot, long_SL_plot, color.new(color.red, 85), 'Long SL plot')
fill(entry_plot, long_TP_plot, color.new(color.green, 85), 'Long TP plot')
// ------------- for short ---------- \\ 
fill(entry_plot, short_SL_plot, color.new(color.red, 85), 'Short SL plot')
fill(entry_plot, short_TP_plot, color.new(color.green, 85), 'Short TP plot')

// This Pine Script® code is subject to the terms of the Mozilla Public License 2.0 at https://mozilla.org/MPL/2.0/
// © AIScripts

//@version=6
strategy("Session Opening Range Breakout (ORBO)",
     overlay           = true,
     initial_capital   = 100000,
     default_qty_type  = strategy.percent_of_equity,
     default_qty_value = 10,
     commission_type   = strategy.commission.percent,
     commission_value  = 0.01)

//──────────────────────────────
// Inputs
//──────────────────────────────
orSession = input.session("0930-0950", "Opening range session")
showRange = input.bool(true, "Show OR levels")
fillRange = input.bool(true, "Fill range body")

//──────────────────────────────
// Session & day detection
//──────────────────────────────
inSession = not na(time(timeframe.period, orSession))
isNewDay  = ta.change(time("D")) != 0

//──────────────────────────────
// Track Opening Range High / Low
//──────────────────────────────
var float orHigh = na
var float orLow  = na

// Reset OR levels at the start of a new day
if isNewDay
    orHigh := na
    orLow  := na

// Build opening range during the session
if inSession
    orHigh := na(orHigh) ? high : math.max(orHigh, high)
    orLow  := na(orLow)  ? low  : math.min(orLow, low)

//──────────────────────────────
// Breakout logic (after OR session ends)
//──────────────────────────────
sessionFinished = not inSession and not na(orHigh) and not na(orLow)

longBreak  = sessionFinished and ta.crossover(close, orHigh)
shortBreak = sessionFinished and ta.crossunder(close, orLow)

if longBreak
    strategy.entry("OR Long", strategy.long)

if shortBreak
    strategy.entry("OR Short", strategy.short)

//──────────────────────────────
// Visuals
//──────────────────────────────
plotOrHigh = plot(
     showRange ? orHigh : na,
     title = "OR High",
     color = color.new(color.green, 0),
     style = plot.style_linebr)

plotOrLow = plot(
     showRange ? orLow : na,
     title = "OR Low",
     color = color.new(color.red, 0),
     style = plot.style_linebr)

// Global-scope fill (required in Pine)
fillColor = showRange and fillRange ? color.new(color.yellow, 90) : na
fill(plotOrHigh, plotOrLow, fillColor)

// Highlight while OR is being built
bgcolor(inSession ? color.new(color.yellow, 92) : na)

// This Pine Script™ code is subject to the terms of the Mozilla Public License 2.0 at https://mozilla.org/MPL/2.0/
// © Tamil_FNO_Trader

// @version=5
indicator(title="ORB With Buffer, Target & Stop Loss", shorttitle="ORB With Buffer ", overlay=true)

// User Input To Enable / Disable, Either / Both Side Levels
bullishbreakout = input(true, title="Bullish Target & SL")
bearishbreakout = input(true, title="Bearish Target & SL")

// Identify High & Low for Selected Scripts
prevClose = request.security(syminfo.tickerid, "D", close[1])

is_newbar(res) => ta.change(time(res)) != 0

adopt(r, s) =>  request.security(syminfo.tickerid, r, s)

open_range_high = ta.valuewhen(is_newbar('D'),high,0)  
open_range_low = ta.valuewhen(is_newbar('D'),low,0)

// Buffer_Calculations For Buffer, TP & SL Levels
Buffer_Calc = prevClose * 0.001
TP_SL_Calc = prevClose * 0.011

// Plot ORB, Buffer, TP & SL Levels
var orbhigh = plot(adopt('15', open_range_high), color = color.blue, linewidth=1, title = "ORB High")
var bufferhigh = plot(adopt('15', (open_range_high+Buffer_Calc)), color = color.blue, linewidth=1, title = "Buffer High")

var orblow = plot(adopt('15', open_range_low), color = color.blue, linewidth=1, title = "ORB Low" )
var bufferlow = plot(adopt('15', (open_range_low-Buffer_Calc)), color = color.blue, linewidth=1, title = "Buffer Low")

buytarget = plot(bullishbreakout ? adopt('15', (open_range_high+TP_SL_Calc)): na, color = color.green, linewidth=1, title = "Buy Target" )
buystoploss = plot(bullishbreakout ? adopt('15', open_range_high - TP_SL_Calc + (Buffer_Calc * 2)):na, color = color.red, linewidth = 1, title = "Buy Stop Loss")

selltarget = plot(bearishbreakout ? adopt('15', (open_range_low-TP_SL_Calc)): na, color = color.green, linewidth=1, title = "Sell Target")
sellstoploss = plot(bearishbreakout ? adopt('15', open_range_low + TP_SL_Calc - (Buffer_Calc *2)):na, color = color.red, linewidth = 1, title = "Sell Stop Loss")

// Fill Buffer Zons
fill(orbhigh, bufferhigh, color=color.new(color.blue, 70), title = "Bullish Buffer BG")
fill(orblow, bufferlow, color=color.new(color.blue, 70), title = "Bearish Buffer BG")

// Draw Labels to Visualize All Levels
drawLabel(yloc, label_text, color) =>
    var label_id = label.new(bar_index, na, text = label_text, color = color, style = label.style_label_lower_left, textcolor = color.white)
    label.set_xy(label_id, bar_index, yloc)

drawLabel(bullishbreakout ? (adopt('15', (open_range_high+Buffer_Calc))) : na, "Buy", color.green)
drawLabel(bearishbreakout ? (adopt('15', (open_range_low-Buffer_Calc))) : na, "Sell", color.red)

drawLabel(bullishbreakout ? (adopt('15', (open_range_high+TP_SL_Calc))) : na, "Buy TP", color.green)
drawLabel(bullishbreakout ? (adopt('15', open_range_high - TP_SL_Calc + (Buffer_Calc * 2))) : na, "Buy SL", color.red)

drawLabel(bearishbreakout ? (adopt('15', (open_range_low-TP_SL_Calc))) : na, "Sell TP", color.green) 
drawLabel(bearishbreakout ? (adopt('15', open_range_low + TP_SL_Calc - (Buffer_Calc *2))) : na, "Sell SL", color.red)

// This Pine Script® code is subject to the terms of the Mozilla Public License 2.0 at https://mozilla.org/MPL/2.0/
// © BruzX

//@version=6
indicator("Opening Range Retest", overlay = true)

// ╔───────────────────────────────────────────────────────────────────────────────────╗
// │                                                                                   │
// │ __/\\\\\\\\\\\\\______/\\\\\\\\\______/\\\________/\\\__/\\\\\\\\\\\\\\\_         │
// │  _\/\\\/////////\\\__/\\\///////\\\___\/\\\_______\/\\\_\////////////\\\__        │
// │   _\/\\\_______\/\\\_\/\\\_____\/\\\___\/\\\_______\/\\\___________/\\\/___       │
// │    _\/\\\\\\\\\\\\\\__\/\\\\\\\\\\\/____\/\\\_______\/\\\_________/\\\/_____      │
// │     _\/\\\/////////\\\_\/\\\//////\\\____\/\\\_______\/\\\_______/\\\/_______     │
// │      _\/\\\_______\/\\\_\/\\\____\//\\\___\/\\\_______\/\\\_____/\\\/_________    │
// │       _\/\\\_______\/\\\_\/\\\_____\//\\\__\//\\\______/\\\____/\\\/___________   │
// │        _\/\\\\\\\\\\\\\/__\/\\\______\//\\\__\///\\\\\\\\\/____/\\\\\\\\\\\\\\\_  │
// │         _\/////////////____\///________\///_____\/////////_____\///////////////__ │
// │                                                                                   │
// ╚───────────────────────────────────────────────────────────────────────────────────╝

// ---- Enums
//#region ---- Enums

//@enum                 Enum to hold to current retest state between bars
//@field inactive       No retest is primed to trigger
//@field primedLong     A top-side retest is primed to trigger
//@field priumedShort   A bottom-side retest is primed to trigger
enum PlayState
    inactive
    primedLong
    primedShort
    
//@enum                 Enum to specify the direction of the marker or alert that was triggered on the current bar
//@field none           Nothing triggered
//@field primedLong     A top-side marker/alert triggered
//@field priumedShort   A bottom-side marker/alert triggered
enum AlertTrigger
    none
    long
    short

//#endregion ---- Enums

// ---- UDTs
//#region ---- UDTs
//#endregion ---- UDTs

// ---- Constants
//#region

const bool DEBUG_MODE = false

//#endregion

// ---- Inputs
//#region

string barsOrMinutes = input.string("Bars", "Bars or minutes", [ "Bars", "Minutes"], tooltip = "Specifies whether the periods specifed below are bars or minutes. Fractional periods are always rounded up.")
int orPeriod = input.int(1, "Opening range period", minval = 1, tooltip = "Number of periods on the chart timeframe that are considered to form the opening range")
int restPeriod = input.int(3, "Resting period", minval = 1, tooltip = "Minimum number of periods that must close outside the opening range after it ends or since the last retest until the next retest can be triggered")
float retestTolerance = input.float(0, "Retest tolerance %", minval = 0, maxval = 50, step = 1, tooltip = "Specifies a retest tolerance as a percentage of the opening range. A retest marker or alert will be trigger if the price comes with this percentage of the opening range top or bottom.")
string alertActiveSession = input.session("0930-1000", "Alert active time range", tooltip = "Time range during which retest markers are shown and user-created retest alerts triggered. The indicator always starts looking for retests from the opening range and continues until the end of the regular market, but with this setting, you can limit the markers and alerts to a time range. For futures, the start time of this setting is taken to be the opening time.")
bool extendBox = input.bool(true, "Extend opening range box", tooltip = "Continue to extend the opening range box even after the end of the alert active time range until end of regular market.")
color boxColour = input.color(color.rgb(178,235,242,80), "Opening range box colour")
color lineColour = input.color(color.blue, "Opening range line colour")

//#endregion

// ---- Functions
//#region

//@function             Utility function for debug logging.
//@param logPredicate   Predicate to allow control of which bar the debug function creates output. Setting to true will produce a message on every bar
//@param message        The string to log
//@returns              Nothing
//Dependency            Global const bool DEBUG_MODE controlling whether this produces any log output
debug(bool logPredicate, string message) =>
    if DEBUG_MODE and logPredicate
        log.info(message)

//#endregion

// ---- Logic
//#region

var bool inOR = false //In opening range?
var float orHigh = na // Opening range high
var float orLow = na // Opening range low
var float orRange = na // Opening range
var int biStart = na //bar_index of the resting counter start
var PlayState playState = na // Holds the retest state between bars
AlertTrigger alertTrigger = AlertTrigger.none //Direction of the alert/marker trigger on this bar
var box ORBox = na // Handle for the opening range box drawing
var bool sessionReset = true

if timeframe.isdwm
    runtime.error("Indicator is not intended for a D/W/M timeframe")

// If periods are specified in minutes, convert to bars. 
if barsOrMinutes == "Minutes"        
    orPeriod := math.ceil(orPeriod * (timeframe.isseconds? 60 : 1) / timeframe.multiplier)
    restPeriod := math.ceil(orPeriod * (timeframe.isseconds? 60 : 1) / timeframe.multiplier)

bool startBar = syminfo.type == "futures" ? not na(time(timeframe.period, alertActiveSession)) and na(time(timeframe.period, alertActiveSession))[1] : session.isfirstbar_regular

// Set everything up on the first bar at the regular market open
if startBar
    biStart := bar_index
    inOR := true
    playState := PlayState.inactive

// Functions need to run on every for consistent behaviour
float runningHigh = ta.highest(nz(ta.barssince(startBar or barstate.isfirst)) + 1)
float runningLow = ta.lowest(nz(ta.barssince(startBar or barstate.isfirst)) + 1)

if inOR
    // If in opening range time window...
    if bar_index == biStart + orPeriod - 1
        // If the bar is the last one in the opening range time window

        orHigh := runningHigh
        orLow := runningLow
        orRange := orHigh - orLow
        sessionReset := false

        if barstate.isconfirmed
            ORBox := box.new(biStart, orHigh, bar_index, orLow, border_width = 0, bgcolor = boxColour)
            line.new(bar_index,orLow, bar_index, orHigh, color = lineColour, style = line.style_dashed)

        biStart := bar_index
        inOR := false

else // not inOR

    if session.islastbar_regular
        sessionReset := true

    if not sessionReset
        // Updates the right side of the OR box during the market (box ends at start or post-market)
        if extendBox or not na(time(timeframe.period, alertActiveSession))
            ORBox.set_right(bar_index) 
    
    // If we're primed to trigger...
    if playState != PlayState.inactive and session.ismarket        
        // Check if we can trigger
        alertTrigger := switch playState
            // Check closes are on same side
            PlayState.primedLong => low <= orHigh + orRange * retestTolerance / 100 ? AlertTrigger.long : AlertTrigger.none
            PlayState.primedShort => high >= orLow - orRange * retestTolerance / 100 ? AlertTrigger.short : AlertTrigger.none
        
        // If we trigered...
        if alertTrigger != AlertTrigger.none
            // Reset variables
            playState := PlayState.inactive
            biStart := bar_index
    
    // Count reset conditions
    if   close >= orLow and close <= orHigh // Close inside OR...
      or close <= orLow and close[1] >= orHigh // Big red bar crossing OR
      or close >= orHigh and close[1] <= orLow // Big green bar crossing OR
        // Reset variables for next bar
        playState := PlayState.inactive
        biStart := bar_index - (close >= orHigh or close <= orLow ? 1 : 0) // If we crossed the OR with a big green/red candle, set biStart to the previous bar, since on this bar we closed outside the OR so it should count towards the resting period.

    // If we had "restPeriod" closes outside the OR...
    if bar_index == biStart + restPeriod
        // Prime for next bar
        playState := switch
            close > orHigh => PlayState.primedLong
            close < orLow => PlayState.primedShort    

//#endregion

// ---- Visuals
//#region

plotshape(not na(time(timeframe.period, alertActiveSession)) and alertTrigger == AlertTrigger.long ? orHigh : na, "High side retest", style = shape.labelup, location = location.belowbar, color = color.green, size=size.small)
plotshape(not na(time(timeframe.period, alertActiveSession)) and alertTrigger == AlertTrigger.short ? orLow : na, "Low side retest", style = shape.labeldown, location = location.abovebar, color = color.red, size=size.small)

//#endregion

// ---- Alerts
//#region ---- Alerts

alertcondition(not na(time(timeframe.period, alertActiveSession)) and alertTrigger == AlertTrigger.long, "Top-side opening range retest", "Top-side opening range retest on {{ticker}} at {{time}}")
alertcondition(not na(time(timeframe.period, alertActiveSession)) and alertTrigger == AlertTrigger.short, "Bottom-side opening range retest", "Bottom-side opening range retest on {{ticker}} at {{time}}")
alertcondition(not na(time(timeframe.period, alertActiveSession)) and alertTrigger != AlertTrigger.none, "All opening range retests", "Opening range retest on {{ticker}} at {{time}}")

//#endregion ---- Alerts

//@version=2

//  Opening Range (OR) for Forex 24 hour regular session.  This is not for regular market day sessions addressed in a separate script.

//   This script fixes four issues:
//  syntax error when code compiles 
//  messed up opening range the day after a holiday Monday
//  flaky plotting of the opening range and targets that required page reloading 
//  TradingView problems with starting forex session at 1700 hours EST/EDT when using certain securities eg FX_IDC currently (Jan 2017)

//  Additions in his code are more options for trading range

//  Time compensation option for  some securities that incorrectly start sessions at 1200 hrs instead of 1700 hrs NY time 
//  - this glitch is likely temporary but present when this script update was created
//  More opening range time period choices

//  Opening Range Targets:
//  Opening Range Targets as per Leaf_West
//  Targets are set at 127% , 162%, 200 %, 262 %, 362%, 423%, 685%, 1109% and 1794% and this can be traded intraday 
//  using methods described here charts-by-leaf.com  I also have some Leaf West PDFs that describe how the targets are set 
//  and how they are traded.  There are others that use opening range.
//  You can adjust targets as you like in the dialogue box.  
//  The 362%, 423%, 685%, 1109% and 1794% Targets will not be displayed unless selected in the dialogue box.
//  I have also included fib targets of yesterday's daily range

//  The Time Session Glitch and the Fix:
//  The script will correctly default to 1700 hrs to 1700hrs EDT/EST session for FXCM.  
//  Strangely some securities appear to erroneously start their session at 1200 hrs ie. My guess is that they are somehow 
//  tied to GMT+0 instead of New York time (GMT+5).  See this for yourself by selecting EURUSD using the FXCM exchange 
//  (FX:EURUSD) and then EURUSD from the IDC exchange (FX_IDC:EURUSD).  The FX-IDC session opening range starts 5 hours
//  before it actually should at 1700 hrs EDT/EST.  To correct for this  I have implemented an automatic fix (default) and a
//  user selected  "5 hour time shift adjust. ment needed on some securities".
//  There is also a 4 hour time shift button which might be necessary when New York reverts from Eastern Standard Time 
//  to Eastern Daylight Time (1 hour difference) in March (and then back again in November). In the default auto adjust mode you 
//  will need to select the 1 hour time shift.  That is if this glitch still exists at that time.   
//  I have looked at other scripts, other than my own and where the script is available,  that need to use information 
//  about the opening bar and all have the same time shift issue


//  What are the choices for Opening Range?
//  The dialogue box offers the standard TradingView options.
//  Also where you see Pick Opening Range 1 to 12 hours , SET TO 0 To USE LINE ABOVE TO DETERMINE OR LENGTH
//  As the note says a number other than 0 will override the standard options from the line above
//  The dialogue box below in offers choices by hours 1 to 12.  A number greater than 12 will still only give
//  720 minutes (12 hours) for the length of Opening Range.  

//  What sessions within the FOREX time-frame are available?
//  The default is 1700 hours to 1700 hours EST/EDT
//  Check any one (only one) of the time periods to change the opening range period to suit.
//  New York opens at 8:00 am to 5:00 pm EST (EDT)
//  Tokyo opens at 7:00 pm to 4:00 am EST (EDT)
//  Sydney opens at 5:00 pm to 2:00 am EST (EDT)
//  London opens at 3:00 am to 12:00 noon EST (EDT)

//  There is a build your own session (click the button to select)  
//  The two lines for inputting session times are almost identical except that the second line starts the 
//   be the same as each other. 
//  The default for the build your own session is 2200 hours to 2200 hours. As of the time of publishing
//   this plots EURUSD FX-IDC just right. The GMT+5 and GMT+4 do not apply to this selection. 
//  See my comments above on this strange aberration.

//  The opening range targets within the upper and lower boundary of the OR
//  There is an option in the dialogue box to display fib targets within Opening Range itself
//  you may plot from top down or bottom up.  There is little difference in direction 
//  for the five values plotted (.236, .382, .5, .618, .786) however .236 and .786 are not quite symmetrical
//  you can switch them as the direction of price changes - if you so desire.
//  In the default situation only the .5 of target within the opening range is shown.
//  The script originated from work done by Chris Moody.  It has changed significantly but there are remnants
//  of that script lurking within.

//  Cheers Jayy










