// SuperTrend parameters
atrPeriod = input.int(11, "ATR Period", minval=1)
factor = input.float(2.0, "Factor", step=0.1)
[supertrend, direction] = ta.supertrend(factor, atrPeriod)

// SuperTrend visualization
plot(supertrend, color=direction < 0 ? color.red : color.green, linewidth=2)

// Time parameters for session opening
h = input.int(9, "Hour", minval=0, maxval=23)
m = input.int(30, "Minute", minval=0, maxval=59) // Default to US session open (9:30 EST)
gmt = input.string("America/New_York", "GMT", options=["America/New_York", "Asia/Kolkata", "Europe/London"])
orbLength = input.int(5, "ORB Candle Count", minval=1)

// Volume filter
volumeFilterEnabled = input.bool(true, "Enable Volume Filter")
volumeLength = input.int(50, "Volume MA Period", minval=1)
volumeMA = ta.sma(volume, volumeLength)
volumeFilter = volume > volumeMA

// ORB range calculation
var float s_high = na
var float s_low = na

// Arrays to store high/low of ORB candles
var highs = array.new_float(orbLength)
var lows = array.new_float(orbLength)

// Reset arrays at the start of new session
if (hour(time, gmt) == h and minute(time, gmt) == m)
    array.clear(highs)
    array.clear(lows)

// Fill arrays with high/low values during ORB formation period
if hour(time, gmt) >= h and minute(time, gmt) >= m and array.size(highs) < orbLength
    array.push(highs, high)
    array.push(lows, low)

// Calculate ORB range after collecting all required candles
if array.size(highs) == orbLength
    s_high := array.max(highs)
    s_low := array.min(lows)

plot(s_high, color=color.green, style=plot.style_cross)
plot(s_low, color=color.red, style=plot.style_cross)

// Entry conditions
long_condition = close > s_high and close[1] <= s_high and close > open and direction < 0
short_condition = close < s_low and close[1] >= s_low and close < open and direction > 0

// Apply volume filter
filtered_long_condition = volumeFilterEnabled ? (long_condition and volumeFilter) : long_condition
filtered_short_condition = volumeFilterEnabled ? (short_condition and volumeFilter) : short_condition

// Position management - FIXED: Added logic to close positions on opposite breakout
in_long_position = strategy.position_size > 0
in_short_position = strategy.position_size < 0

// Exit conditions for opposite breakouts
exit_long_condition = close < s_low
exit_short_condition = close > s_high

// Stop loss and take profit calculation
stop_loss_long = s_low
stop_loss_short = s_high
risk_reward_ratio = input.float(3.0, "Risk/Reward Ratio")
take_profit_long = close + (close - stop_loss_long) * risk_reward_ratio
take_profit_short = close - (stop_loss_short - close) * risk_reward_ratio

// Long entry (only if SuperTrend is bearish)
if (filtered_long_condition and strategy.position_size == 0 and direction < 0)
    strategy.entry("Long", strategy.long)
    strategy.exit("Take Profit/Stop Loss Long", from_entry="Long", stop=stop_loss_long, limit=take_profit_long)

// Short entry (only if SuperTrend is bullish)
if (filtered_short_condition and strategy.position_size == 0 and direction > 0)
    strategy.entry("Short", strategy.short)
    strategy.exit("Take Profit/Stop Loss Short", from_entry="Short", stop=stop_loss_short, limit=take_profit_short)

// Close positions on opposite breakout - NEW: Added explicit exit logic
if (in_long_position and exit_long_condition)
    strategy.close("Long", comment="Exit Long on Opposite Breakout")

if (in_short_position and exit_short_condition)
    strategy.close("Short", comment="Exit Short on Opposite Breakout")

//@version=6
strategy(
     title              = "ORB Breakout",
     overlay            = true,
     initial_capital    = 100000,
     pyramiding         = 0,
     margin_long        = 12.5,
     margin_short       = 12.5,
     commission_type    = strategy.commission.cash_per_contract,
     commission_value   = 0.05
)

// ----------------------------------------------------------------------------------------
// Inputs
// ----------------------------------------------------------------------------------------
riskUsd      = input.float(2000, "Risk per trade ($)", step=50)
rr           = input.float(2.0, "Reward/Risk", step=0.25)

sessionRTH   = input.session("0930-1600", "Regular session (exchange time)")
orbSession   = input.session("0930-0945", "Opening range window")
entryWindow  = input.session("0930-1200", "Entry window (no entries after)")
flatWindow   = input.session("1550-1600", "Flat window (close at 15:50)")

// If your CFD needs integer sizing, keep these at 1.
// If you need micro sizing, set minQty=0.1 and qtyStep=0.1, etc.
minQty       = input.float(1.0, "Min Qty", step=0.1)
qtyStep      = input.float(1.0, "Qty Step", step=0.1)

// ----------------------------------------------------------------------------------------
// Safety: intended for 5m charts
// ----------------------------------------------------------------------------------------
is5m = timeframe.isintraday and timeframe.multiplier == 5

// ----------------------------------------------------------------------------------------
// Session filters (exchange-time consistent)
// ----------------------------------------------------------------------------------------
inRTH      = not na(time(timeframe.period, sessionRTH))
inORB      = not na(time(timeframe.period, orbSession))
inEntryWin = not na(time(timeframe.period, entryWindow))
inFlatWin  = not na(time(timeframe.period, flatWindow))

afterCutoff = inRTH and not inEntryWin

// New trading day
newDay = ta.change(time("D")) != 0

// ----------------------------------------------------------------------------------------
// ORB state
// ----------------------------------------------------------------------------------------
var float orbHigh  = na
var float orbLow   = na
var bool  orbReady = false

// 1 FILLED trade per day
var bool hasTradedToday = false
var int closedTradesAtDayStart = 0

// Persistent setup states (so retest fills are not missed)
var bool  longSetupActive  = false
var bool  shortSetupActive = false

// Store anchored risk params from the breakout/breakdown candle
var float longStopStored   = na
var float longTargetStored = na
var float longQtyStored    = na

var float shortStopStored   = na
var float shortTargetStored = na
var float shortQtyStored    = na

// ----------------------------------------------------------------------------------------
// Reset on new day
// ----------------------------------------------------------------------------------------
if newDay
    orbHigh := na
    orbLow  := na
    orbReady := false
    hasTradedToday := false
    closedTradesAtDayStart := strategy.closedtrades

    longSetupActive := false
    shortSetupActive := false
    longStopStored := na
    longTargetStored := na
    longQtyStored := na
    shortStopStored := na
    shortTargetStored := na
    shortQtyStored := na

    strategy.cancel("L")
    strategy.cancel("S")

// ----------------------------------------------------------------------------------------
// Detect any trade occurred today (robust, incl. same-bar round trips)
// ----------------------------------------------------------------------------------------
tradeHappenedToday =
     (strategy.opentrades > 0) or (strategy.closedtrades > closedTradesAtDayStart)

if tradeHappenedToday and not hasTradedToday
    hasTradedToday := true
    longSetupActive := false
    shortSetupActive := false
    strategy.cancel("L")
    strategy.cancel("S")

// ----------------------------------------------------------------------------------------
// Build ORB (09:30–09:45)
// ----------------------------------------------------------------------------------------
if inORB and inRTH and is5m
    orbHigh := na(orbHigh) ? high : math.max(orbHigh, high)
    orbLow  := na(orbLow)  ? low  : math.min(orbLow, low)

// Lock ORB after window ends
if not inORB and inRTH and is5m and not orbReady and not na(orbHigh) and not na(orbLow)
    orbReady := true

// ----------------------------------------------------------------------------------------
// Signal definitions
// ----------------------------------------------------------------------------------------
longBreak  = orbReady and inRTH and close > orbHigh
shortBreak = orbReady and inRTH and close < orbLow

// FVG filter vs 2 bars ago (10m on 5m chart)
longFVG  = low > high[2]
shortFVG = high < low[2]

// Entry prices at ORB boundaries (retest)
longEntryPrice  = orbHigh
shortEntryPrice = orbLow

// ----------------------------------------------------------------------------------------
// Qty rounding helpers
// ----------------------------------------------------------------------------------------
roundToStep(x, step) =>
    step <= 0 ? x : math.round(x / step) * step

// ----------------------------------------------------------------------------------------
// Activate setup on breakout/breakdown candle (store anchored SL/TP/Qty)
// Only if:
// - within entry window
// - no trade filled yet today
// - flat/no position
// - no other setup active
// --------------------
canArmSetup =
     is5m and inRTH and inEntryWin and orbReady and not hasTradedToday and strategy.position_size == 0 and not (longSetupActive or shortSetupActive)

// LONG setup arm
if canArmSetup and longBreak and longFVG
    rawStop = low[2]  // your rule: SL = low of 2-prior candle of breakout candle
    stop    = math.min(rawStop, longEntryPrice - syminfo.mintick)  // enforce valid side
    riskPts = longEntryPrice - stop

    if riskPts > 0
        qtyRaw = riskUsd / (riskPts * syminfo.pointvalue)
        qty    = roundToStep(qtyRaw, qtyStep)

        if qty >= minQty
            longStopStored   := stop
            longTargetStored := longEntryPrice + rr * riskPts
            longQtyStored    := qty
            longSetupActive  := true

// SHORT setup arm
if canArmSetup and shortBreak and shortFVG
    rawStop = high[2] // your rule: SL = high of 2-prior candle of breakdown candle
    stop    = math.max(rawStop, shortEntryPrice + syminfo.mintick) // enforce valid side
    riskPts = stop - shortEntryPrice

    if riskPts > 0
        qtyRaw = riskUsd / (riskPts * syminfo.pointvalue)
        qty    = roundToStep(qtyRaw, qtyStep)

        if qty >= minQty
            shortStopStored   := stop
            shortTargetStored := shortEntryPrice - rr * riskPts
            shortQtyStored    := qty
            shortSetupActive  := true

// ----------------------------------------------------------------------------------------
// Maintain pending orders while setup is active
// (This is the key fix so fills 1–N candles later are NOT missed.)
// ----------------------------------------------------------------------------------------
canMaintainOrders = is5m and inRTH and inEntryWin and strategy.position_size == 0 and not hasTradedToday

if canMaintainOrders and longSetupActive
    strategy.entry("L", strategy.long, qty=longQtyStored, limit=longEntryPrice)
    strategy.exit("L-X", from_entry="L", stop=longStopStored, limit=longTargetStored)

if canMaintainOrders and shortSetupActive
    strategy.entry("S", strategy.short, qty=shortQtyStored, limit=shortEntryPrice)
    strategy.exit("S-X", from_entry="S", stop=shortStopStored, limit=shortTargetStored)

// ----------------------------------------------------------------------------------------
// Cancel pending orders after cutoff and after RTH
// ----------------------------------------------------------------------------------------
if afterCutoff
    strategy.cancel("L")
    strategy.cancel("S")
    longSetupActive := false
    shortSetupActive := false

if not inRTH
    strategy.cancel("L")
    strategy.cancel("S")
    longSetupActive := false
    shortSetupActive := false

// ----------------------------------------------------------------------------------------
// Flat at 15:50 (close same day)
// Note: on 5m chart this happens at the close of the 15:50 bar.
// ----------------------------------------------------------------------------------------
if inRTH and inFlatWin and strategy.position_size != 0
    strategy.close("L")
    strategy.close("S")

// ----------------------------------------------------------------------------------------
// Visuals
// ----------------------------------------------------------------------------------------
// Plot ORB lines only until 12:00 (exchange time)
plotORB = inRTH and inEntryWin
plot(plotORB ? orbHigh : na, "ORB High", style=plot.style_linebr, linewidth=2, color=color.new(#18b79c, 0))
plot(plotORB ? orbLow  : na, "ORB Low",  style=plot.style_linebr, linewidth=2, color=color.new(#5d606b, 0))

//@version=6
strategy("ORB Breakout", 
     overlay=true, 
     fill_orders_on_standard_ohlc=true, 
     pyramiding=0,
     initial_capital=50000,
     default_qty_type=strategy.fixed,
     default_qty_value=1,
     commission_type=strategy.commission.cash_per_contract,
     commission_value=4.0,
     slippage=2,
     margin_long=1,
     margin_short=1)

// ══════════════════════════════════════════════════════════════════════════════
// INPUTS
// ══════════════════════════════════════════════════════════════════════════════

i_orbBars       = input.int(3, "ORB Bars", minval=1, maxval=20)
i_sessionString = input.session("0930-1730", "Trading Session")
i_timeZone      = input.string("America/New_York", "Timezone", options=["America/New_York", "America/Chicago", "Europe/London", "Asia/Tokyo"])
i_maxTrades     = input.int(2, "Max Trades Per Day", minval=1, maxval=10)

// Risk Management Mode
i_riskMode      = input.string("Breakout Candle", "TP/SL Mode", options=["Fixed Points", "Breakout Candle"], group="Risk Management", tooltip="Fixed Points: Set exact point values. Breakout Candle: Stop at candle low/high, TP as ratio of risk")

// Fixed Points Settings
i_fixedTpPoints = input.float(20.0, "Take Profit (points)", minval=1.0, maxval=500.0, step=1.0, group="Fixed Points Mode", tooltip="Fixed distance in points from entry")
i_fixedSlPoints = input.float(10.0, "Stop Loss (points)", minval=1.0, maxval=500.0, step=1.0, group="Fixed Points Mode", tooltip="Fixed distance in points from entry")

// Breakout Candle Settings
i_rrRatio       = input.float(1.0, "Risk:Reward Ratio", minval=0.5, maxval=5.0, step=0.5, group="Breakout Candle Mode", tooltip="1.0 = 1:1 R:R, 2.0 = 1:2 R:R. TP distance = Risk × this value")

// Breakeven (applies to both modes)
i_useBreakeven  = input.bool(true, "Use Breakeven", group="Breakeven")
i_beMultiplier  = input.float(0.5, "Breakeven Trigger (x TP Distance)", minval=0.1, maxval=1.0, step=0.1, group="Breakeven", tooltip="0.5 = move stop to entry when price reaches 50% of TP")

// VWAP Filter
i_useVwapFilter = input.bool(true, "Use VWAP Filter", group="VWAP Filter")
i_vwapSlopeBars = input.int(5, "VWAP Slope Lookback", minval=2, maxval=20, group="VWAP Filter")
i_minVwapSlope  = input.float(0.5, "Min VWAP Slope (points)", minval=0.0, maxval=10.0, step=0.1, group="VWAP Filter")

// Volume Filter
i_useVolumeFilter = input.bool(true, "Use Volume Filter", group="Volume Filter")
i_minVolume       = input.int(2500, "Min Breakout Volume", minval=100, maxval=50000, step=100, group="Volume Filter")

// Candle Strength Filter
i_useCandleFilter    = input.bool(true, "Use Candle Strength Filter", group="Candle Strength")
i_minCandleStrength  = input.float(0.7, "Min Candle Strength (%)", minval=0.5, maxval=0.95, step=0.05, group="Candle Strength", tooltip="0.7 = close must be in top 30% (long) or bottom 30% (short) of candle range")

// ══════════════════════════════════════════════════════════════════════════════
// SESSION DETECTION
// ══════════════════════════════════════════════════════════════════════════════

inSession    = not na(time(timeframe.period, i_sessionString, i_timeZone))
sessionStart = inSession and not inSession[1]
sessionEnd   = not inSession and inSession[1]

// ══════════════════════════════════════════════════════════════════════════════
// SESSION VWAP
// ══════════════════════════════════════════════════════════════════════════════

var float vwapSum    = 0.0
var float vwapVolSum = 0.0
var float sessionVwap = na

if sessionStart
    vwapSum    := 0.0
    vwapVolSum := 0.0

if inSession
    vwapSum     += hlc3 * volume
    vwapVolSum  += volume
    sessionVwap := vwapVolSum > 0 ? vwapSum / vwapVolSum : na

vwapSlope       = sessionVwap - nz(sessionVwap[i_vwapSlopeBars])
vwapSlopingUp   = vwapSlope > i_minVwapSlope
vwapSlopingDown = vwapSlope < -i_minVwapSlope

// ══════════════════════════════════════════════════════════════════════════════
// VOLUME & CANDLE STRENGTH (evaluated on current bar for order placement)
// ══════════════════════════════════════════════════════════════════════════════

highVolume      = volume >= i_minVolume
candleRange     = high - low
closePosition   = candleRange > 0 ? (close - low) / candleRange : 0.5
bullishStrength = closePosition >= i_minCandleStrength
bearishStrength = closePosition <= (1 - i_minCandleStrength)

// ══════════════════════════════════════════════════════════════════════════════
// ORB CALCULATION
// ══════════════════════════════════════════════════════════════════════════════

var float orbHigh  = na
var float orbLow   = na
var int   barNum   = 0
var bool  orbReady = false

if sessionStart
    orbHigh  := high
    orbLow   := low
    barNum   := 1
    orbReady := i_orbBars == 1
else if inSession and barNum >= 1 and barNum < i_orbBars
    orbHigh := math.max(orbHigh, high)
    orbLow  := math.min(orbLow, low)
    barNum  += 1
    if barNum == i_orbBars
        orbReady := true

orbRange = orbHigh - orbLow

// ══════════════════════════════════════════════════════════════════════════════
// TRADE STATE MANAGEMENT
// ══════════════════════════════════════════════════════════════════════════════

var int   tradesToday    = 0
var float tradeEntry     = na
var float tradeTpLevel   = na
var float tradeSlLevel   = na
var float tradeBeTrigger = na
var bool  beTriggered    = false

if sessionStart
    tradesToday := 0

// ══════════════════════════════════════════════════════════════════════════════
// FILTER CONDITIONS (evaluated each bar for stop order placement)
// ══════════════════════════════════════════════════════════════════════════════

// VWAP Filter - for longs: price above VWAP and VWAP rising
vwapLongOk  = not i_useVwapFilter or (close > sessionVwap and vwapSlopingUp)
vwapShortOk = not i_useVwapFilter or (close < sessionVwap and vwapSlopingDown)

// Volume Filter
volumeOk = not i_useVolumeFilter or highVolume

// Candle Strength Filter
candleLongOk  = not i_useCandleFilter or bullishStrength
candleShortOk = not i_useCandleFilter or bearishStrength

// Can we trade?
canTrade = strategy.position_size == 0 and tradesToday < i_maxTrades and inSession and orbReady

// Combined filter conditions
longFiltersOk  = vwapLongOk and volumeOk and candleLongOk
shortFiltersOk = vwapShortOk and volumeOk and candleShortOk

// ══════════════════════════════════════════════════════════════════════════════
// STOP ORDER PLACEMENT - Entry at exact ORB level
// ══════════════════════════════════════════════════════════════════════════════

// Place/update stop orders each bar if filters pass
// Orders trigger intrabar when price reaches ORB level

if canTrade
    // Long stop order at ORB High
    if longFiltersOk and close < orbHigh  // Only place if price hasn't already broken out
        strategy.entry("Long", strategy.long, stop=orbHigh)
    else
        strategy.cancel("Long")
    
    // Short stop order at ORB Low
    if shortFiltersOk and close > orbLow  // Only place if price hasn't already broken down
        strategy.entry("Short", strategy.short, stop=orbLow)
    else
        strategy.cancel("Short")

// Cancel all pending orders outside session or when can't trade
if not canTrade
    strategy.cancel("Long")
    strategy.cancel("Short")

// ══════════════════════════════════════════════════════════════════════════════
// POSITION MANAGEMENT - Set exits when position opens
// Use CURRENT bar's low/high (the breakout bar) for SL calculation
// ══════════════════════════════════════════════════════════════════════════════

useFixedPoints = i_riskMode == "Fixed Points"

// Long position just opened
if strategy.position_size > 0 and strategy.position_size[1] == 0
    tradesToday += 1
    tradeEntry  := strategy.opentrades.entry_price(0)
    
    if useFixedPoints
        // Fixed Points Mode
        tradeTpLevel := tradeEntry + i_fixedTpPoints
        tradeSlLevel := tradeEntry - i_fixedSlPoints
    else
        // Breakout Candle Mode - use CURRENT bar's low (the breakout bar)
        tradeSlLevel := low
        float risk   = tradeEntry - tradeSlLevel
        // Ensure minimum risk to avoid division issues
        if risk < 1
            risk := 1
        tradeTpLevel := tradeEntry + (risk * i_rrRatio)
    
    // Breakeven trigger
    if i_useBreakeven
        tradeBeTrigger := tradeEntry + ((tradeTpLevel - tradeEntry) * i_beMultiplier)
    else
        tradeBeTrigger := na
    
    beTriggered := false
    strategy.exit("Long Exit", "Long", limit=tradeTpLevel, stop=tradeSlLevel)

// Short position just opened
if strategy.position_size < 0 and strategy.position_size[1] == 0
    tradesToday += 1
    tradeEntry  := strategy.opentrades.entry_price(0)
    
    if useFixedPoints
        // Fixed Points Mode
        tradeTpLevel := tradeEntry - i_fixedTpPoints
        tradeSlLevel := tradeEntry + i_fixedSlPoints
    else
        // Breakout Candle Mode - use CURRENT bar's high (the breakout bar)
        tradeSlLevel := high
        float risk   = tradeSlLevel - tradeEntry
        // Ensure minimum risk to avoid division issues
        if risk < 1
            risk := 1
        tradeTpLevel := tradeEntry - (risk * i_rrRatio)
    
    // Breakeven trigger
    if i_useBreakeven
        tradeBeTrigger := tradeEntry - ((tradeEntry - tradeTpLevel) * i_beMultiplier)
    else
        tradeBeTrigger := na
    
    beTriggered := false
    strategy.exit("Short Exit", "Short", limit=tradeTpLevel, stop=tradeSlLevel)

// ══════════════════════════════════════════════════════════════════════════════
// BREAKEVEN LOGIC
// ══════════════════════════════════════════════════════════════════════════════

if strategy.position_size > 0 and not beTriggered and not na(tradeBeTrigger) and i_useBreakeven
    if high >= tradeBeTrigger
        beTriggered  := true
        tradeSlLevel := tradeEntry
        strategy.exit("Long Exit", "Long", limit=tradeTpLevel, stop=tradeEntry)

if strategy.position_size < 0 and not beTriggered and not na(tradeBeTrigger) and i_useBreakeven
    if low <= tradeBeTrigger
        beTriggered  := true
        tradeSlLevel := tradeEntry
        strategy.exit("Short Exit", "Short", limit=tradeTpLevel, stop=tradeEntry)

// ══════════════════════════════════════════════════════════════════════════════
// POSITION CLOSED - Reset state
// ══════════════════════════════════════════════════════════════════════════════

if strategy.position_size == 0 and strategy.position_size[1] != 0
    tradeEntry      := na
    tradeTpLevel    := na
    tradeSlLevel    := na
    tradeBeTrigger  := na
    beTriggered     := false

// ══════════════════════════════════════════════════════════════════════════════
// SESSION END - Close positions and cancel orders
// ══════════════════════════════════════════════════════════════════════════════

if sessionEnd
    strategy.close_all(comment="Session End")
    strategy.cancel("Long")
    strategy.cancel("Short")
    tradeEntry      := na
    tradeTpLevel    := na
    tradeSlLevel    := na
    tradeBeTrigger  := na
    beTriggered     := false

// ══════════════════════════════════════════════════════════════════════════════
// VISUALIZATION
// ══════════════════════════════════════════════════════════════════════════════

// Session backgrounds
orbForming = inSession and barNum >= 1 and barNum <= i_orbBars and not orbReady
bgcolor(orbForming ? color.new(color.orange, 85) : na, title="ORB Forming")
bgcolor(inSession and orbReady ? color.new(color.green, 95) : na, title="Trading Session")

// ORB Levels
plot(orbReady and inSession ? orbHigh : na, "ORB High", color.green, 2, plot.style_linebr)
plot(orbReady and inSession ? orbLow : na, "ORB Low", color.red, 2, plot.style_linebr)

// Session VWAP
vwapColor = vwapSlopingUp ? color.green : vwapSlopingDown ? color.red : color.gray
plot(inSession ? sessionVwap : na, "Session VWAP", vwapColor, 2, plot.style_linebr)

// Trade Levels (only when in position)
plot(strategy.position_size != 0 ? tradeEntry : na, "Entry", color.white, 1, plot.style_linebr)
plot(strategy.position_size != 0 ? tradeTpLevel : na, "Take Profit", color.lime, 2, plot.style_linebr)
plot(strategy.position_size != 0 ? tradeSlLevel : na, "Stop Loss", color.red, 2, plot.style_linebr)
plot(strategy.position_size != 0 and not beTriggered and i_useBreakeven ? tradeBeTrigger : na, "BE Trigger", color.orange, 1, plot.style_linebr)

// Breakeven active indicator
bgcolor(strategy.position_size != 0 and beTriggered ? color.new(color.blue, 90) : na, title="Breakeven Active")

// Show pending order levels (when order is placed but not yet filled)
pendingLong  = canTrade and longFiltersOk and close < orbHigh
pendingShort = canTrade and shortFiltersOk and close > orbLow

plotshape(pendingLong, "Pending Long", shape.triangleup, location.belowbar, color.new(color.green, 50), size=size.tiny)
plotshape(pendingShort, "Pending Short", shape.triangledown, location.abovebar, color.new(color.red, 50), size=size.tiny)

