            cPrev := orbClose5Prev
            h := orbHigh5
            hPrev := orbHigh5Prev
            l := orbLow5
            lPrev := orbLow5Prev
            justClosed := orbTFClosed5 and barstate.isconfirmed
        else if orbMins == 15
            c := orbClose15
            cPrev := orbClose15Prev
            h := orbHigh15
            hPrev := orbHigh15Prev
            l := orbLow15
            lPrev := orbLow15Prev
            justClosed := orbTFClosed15 and barstate.isconfirmed
        else if orbMins == 30
            c := orbClose30
            cPrev := orbClose30Prev
            h := orbHigh30
            hPrev := orbHigh30Prev
            l := orbLow30
            lPrev := orbLow30Prev
            justClosed := orbTFClosed30 and barstate.isconfirmed
        else
            c := orbClose60
            cPrev := orbClose60Prev
            h := orbHigh60
            hPrev := orbHigh60Prev
            l := orbLow60
            lPrev := orbLow60Prev
            justClosed := orbTFClosed60 and barstate.isconfirmed
    [c, cPrev, h, hPrev, l, lPrev, justClosed]

