//@version=5
strategy("VWAP ORB Pullback Strategy", overlay=true, default_qty_type=strategy.percent_of_equity, default_qty_value=10)

// === INPUTS ===
or_minutes = input.int(15, "Opening Range Minutes")
risk_reward = input.float(1.5, "Risk/Reward Ratio", step=0.1)
use_vwap = input.bool(true, "Use VWAP Filter")

// === TIME FILTER ===
start_time = timestamp("America/New_York", year, month, dayofmonth, 9, 30)
or_end_time = start_time + (or_minutes * 60 * 1000)

// === OPENING RANGE ===
var float or_high = na
var float or_low = na

if (time >= start_time and time <= or_end_time)
    or_high := na(or_high) ? high : math.max(or_high, high)
    or_low := na(or_low) ? low : math.min(or_low, low)

// Reset daily
if (ta.change(time("D")))
    or_high := na
    or_low := na

plot(or_high, color=color.green, title="OR High")
plot(or_low, color=color.red, title="OR Low")

// === VWAP ===
vwap = ta.vwap(close)
plot(vwap, color=color.orange, title="VWAP")

// === EMA (for pullback confirmation) ===
ema9 = ta.ema(close, 9)

// === CONDITIONS ===

// Long Conditions
breakout_long = close > or_high
pullback_long = close > vwap and close > ema9 and low <= vwap

long_condition = breakout_long and pullback_long and time > or_end_time

// Short Conditions
breakout_short = close < or_low
pullback_short = close < vwap and close < ema9 and high >= vwap

short_condition = breakout_short and pullback_short and time > or_end_time

// === RISK MANAGEMENT ===
atr = ta.atr(14)

// Stop/Target
long_stop = close - atr
long_target = close + (atr * risk_reward)

short_stop = close + atr
short_target = close - (atr * risk_reward)

// === EXECUTION ===
if (long_condition)
    strategy.entry("Long", strategy.long)
    strategy.exit("Long Exit", from_entry="Long", stop=long_stop, limit=long_target)

if (short_condition)
    strategy.entry("Short", strategy.short)
    strategy.exit("Short Exit", from_entry="Short", stop=short_stop, limit=short_target)

//@version=5
indicator("ORB Breakout Indicator - NQ1!", overlay=true)

startSession = timestamp("America/New_York", year, month, dayofmonth, 09, 30)
endSession = timestamp("America/New_York", year, month, dayofmonth, 09, 45)

inSession = time >= startSession and time < endSession
var float orbHigh = na
var float orbLow = na
var bool orbSet = false

// Reset ORB values during ORB window
if (inSession)
    orbHigh := na
    orbLow := na
    orbSet := false

// Track High/Low during ORB window
if inSession
    orbHigh := na(orbHigh) ? high : math.max(orbHigh, high)
    orbLow := na(orbLow) ? low : math.min(orbLow, low)

// Lock ORB range
if (not inSession and not orbSet and not na(orbHigh) and not na(orbLow))
    orbSet := true

// Only one signal per day
var bool signalGiven = false
if (dayofweek != dayofweek[1])
    signalGiven := false

// Entry signals (after ORB set)
longSignal = not inSession and orbSet and not signalGiven and close > orbHigh
shortSignal = not inSession and orbSet and not signalGiven and close < orbLow

// Plot breakout arrows
plotshape(longSignal, title="Long Entry", location=location.belowbar, color=color.green, style=shape.arrowup, size=size.small)
plotshape(shortSignal, title="Short Entry", location=location.abovebar, color=color.red, style=shape.arrowdown, size=size.small)

if (longSignal or shortSignal)
    signalGiven := true

// Plot ORB High/Low
plot(inSession or orbSet ? orbHigh : na, title="ORB High", color=color.green, linewidth=1)
plot(inSession or orbSet ? orbLow : na, title="ORB Low", color=color.red, linewidth=1)

//@version=5
indicator("Sourav ORB-RSI-MA Indicator", overlay=true)

// === Inputs ===
emaLength   = input.int(200, "EMA Length")
rsiLength   = input.int(14,  "RSI Length")
rsiMaLength = input.int(9,   "RSI MA Length")

// === Calculations ===
ema200 = ta.ema(close, emaLength)
rsi    = ta.rsi(close, rsiLength)
rsi_ma = ta.sma(rsi, rsiMaLength)

// === Buy & Sell Conditions ===
buyCond  = close > ema200 and rsi > 35 and ta.crossover(rsi, rsi_ma)
sellCond = close < ema200 and rsi < 65 and ta.crossunder(rsi, rsi_ma)

// === Plot EMA ===
plot(ema200, title="200 EMA", color=color.orange, linewidth=2)

// === Buy Signal ===
plotshape(buyCond, title="BUY", style=shape.labelup, color=color.green, size=size.large, text="BUY")

// === Sell Signal ===
plotshape(sellCond, title="SELL", style=shape.labeldown, color=color.red, size=size.large, text="SELL")

