// This indicator plot the ORB range selected by you. IMPORTANT: it works in ANY Time Frame for Intraday Trading ONLY, it means < 1D time frame chart!
// It can be used for any stocks and futures e.g. US500, NAS100, GER40. 
// Inputs:  ORB Range
//          Session Start
//          Time Zone Offset
// For example, for DAX (GER40), Set your ORB range, Session Start 0900, and Time Zone Offset +1
// For US Stocks and US500, NAS100, Set your ORB range, Session Start 0930, and Time Zone Offset -5

//@version=5
indicator(title="ORB - Futures and Stocks (Breakouts + Alerts + ORB Selector)", shorttitle="ORB Selector Futures + Stocks", overlay=true)

// === User Inputs ===
up5on      = input.bool(true, title="Show OR High")
down5on    = input.bool(true, title="Show OR Low")
start_time = input.string("0930", title="Session Start (HHMM)")
utc_offset = input.int(-5, title="UTC Offset (e.g., -5 = New York, +1 = Berlin)", minval=-12, maxval=14)
orb_range  = input.string("5", title="ORB Range Time (minutes)", options=["1", "5", "10", "15", "30", "60"])

// === Parse time string
start_hr  = str.tonumber(str.substring(start_time, 0, 2))
start_min = str.tonumber(str.substring(start_time, 2, 4))

// === Apply 1-hour shift earlier for futures (with safeguard)
adj_start_hr = start_hr > 0 ? start_hr - 1 : 23

// === OR calculation function
f_orb(isHigh) =>
    var float val = na
    new_day = ta.change(time("D"))
    orbMins = str.tonumber(orb_range)
    sess_start = timestamp("UTC", year, month, dayofmonth, int(adj_start_hr - utc_offset), int(start_min))
    sess_end   = sess_start + orbMins * 60 * 1000
    if new_day
        val := na
    if time >= sess_start and time < sess_end
        val := na(val) ? (isHigh ? high : low) : (isHigh ? math.max(val, high) : math.min(val, low))
    val

// === Use 1-minute timeframe to match any ORB granularity
orb_tf = "1"

orbHigh = request.security(syminfo.tickerid, orb_tf, f_orb(true))
orbLow  = request.security(syminfo.tickerid, orb_tf, f_orb(false))

// === Plot OR lines
up5   = plot(up5on   ? orbHigh : na, title="OR High", color=color.teal, linewidth=1)
down5 = plot(down5on ? orbLow  : na, title="OR Low", color=color.orange, linewidth=1)
fill(up5, down5, color=color.white, transp=90)

// === Breakout logic
bullBreakout = ta.crossover(close, orbHigh)
bearBreakout = ta.crossunder(close, orbLow)

// === Plot signals
plotshape(bullBreakout, title="Bullish Breakout", location=location.belowbar, color=color.green, style=shape.arrowup, size=size.small, textcolor=color.white, text="Long")
plotshape(bearBreakout, title="Bearish Breakout", location=location.abovebar, color=color.red, style=shape.arrowdown, size=size.small, textcolor=color.white, text="Short")

// === Alerts
alertcondition(bullBreakout, title="Bullish OR Breakout", message="ORB Bullish Breakout: Price crossed above the Opening Range High")
alertcondition(bearBreakout, title="Bearish OR Breakout", message="ORB Bearish Breakout: Price crossed below the Opening Range Low")

