//@version=5
indicator("First 15min Candle Breakout", overlay=true)

// Input for market open time (default: 9:30 AM EST)
marketOpenHour = input.int(9, "Market Open Hour", minval=0, maxval=23)
marketOpenMinute = input.int(30, "Market Open Minute", minval=0, maxval=59)

// Colors for visualization
bullishColor = input.color(color.new(color.green, 80), "Breakout Above Color")
bearishColor = input.color(color.new(color.red, 80), "Breakout Below Color")
rangeColor = input.color(color.new(color.blue, 90), "15min Range Color")

// Variables to store the first 15min candle high and low
var float first15High = na
var float first15Low = na
var bool capturedRange = false

// Function to check if we're at market open
isMarketOpen = hour == marketOpenHour and minute == marketOpenMinute

// Function to check if we're in the first 15 minutes
isFirst15Min = hour == marketOpenHour and minute >= marketOpenMinute and minute < marketOpenMinute + 15

// Reset at the start of a new day
if ta.change(dayofweek) or (isMarketOpen and not capturedRange[1])
    first15High := na
    first15Low := na
    capturedRange := false

// Capture the high and low during the first 15 minutes
if isFirst15Min and timeframe.period == "15"
    if na(first15High) or high > first15High
        first15High := high
    if na(first15Low) or low < first15Low
        first15Low := low
    capturedRange := true

// For timeframes other than 15min, we need to track bars within the range
if timeframe.period != "15"
    if isFirst15Min
        if na(first15High) or high > first15High
            first15High := high
        if na(first15Low) or low < first15Low
            first15Low := low

    // Mark as captured after 15 minutes have passed
    if hour == marketOpenHour and minute == marketOpenMinute + 15
        capturedRange := true

    // For intraday timeframes less than 15min
    if (hour == marketOpenHour and minute > marketOpenMinute + 15) or (hour > marketOpenHour)
        capturedRange := true

// Detect breakout conditions
breakoutAbove = capturedRange and close > first15High and close[1] <= first15High
breakoutBelow = capturedRange and close < first15Low and close[1] >= first15Low

// Plot the first 15min high and low lines
plot(capturedRange ? first15High : na, "First 15min High", color=color.green, linewidth=2, style=plot.style_line)
plot(capturedRange ? first15Low : na, "First 15min Low", color=color.red, linewidth=2, style=plot.style_line)

// Fill the range
fillColor = capturedRange ? rangeColor : na
h = plot(capturedRange ? first15High : na, display=display.none)
l = plot(capturedRange ? first15Low : na, display=display.none)
fill(h, l, color=fillColor, title="15min Range")

// Plot breakout signals
plotshape(breakoutAbove, "Breakout Above", shape.triangleup, location.belowbar, color=color.green, size=size.small)
plotshape(breakoutBelow, "Breakout Below", shape.triangledown, location.abovebar, color=color.red, size=size.small)

// Background color on breakout
bgcolor(breakoutAbove ? bullishColor : na, title="Bullish Breakout BG")
bgcolor(breakoutBelow ? bearishColor : na, title="Bearish Breakout BG")

// Alerts
alertcondition(breakoutAbove, title="Breakout Above First 15min High", message="Price closed above the first 15min high at {{close}}")
alertcondition(breakoutBelow, title="Breakout Below First 15min Low", message="Price closed below the first 15min low at {{close}}")
alertcondition(breakoutAbove or breakoutBelow, title="Any Breakout", message="Price broke out of first 15min range. Close: {{close}}")

